import subprocess, sys, json
def run(src, args=None):
    a = ['/workspace/executable','-']
    if args: a = ['/workspace/executable'] + args + ['-']
    r = subprocess.run(a, input=src.encode(), capture_output=True)
    return r.returncode, r.stdout.decode('utf-8','replace'), r.stderr.decode('utf-8','replace')
def show(src, args=None):
    c,o,e = run(src,args)
    print("INPUT: " + repr(src))
    print("EXIT: %d" % c)
    if o: print("STDOUT: " + repr(o))
    if e: print("STDERR:")

    if e:
        for line in e.rstrip('\n').split('\n'):
            print("  |" + line)
    print("-"*60)
if __name__ == '__main__':
    for s in sys.argv[1:]:
        show(s)
